// SigRaft - leader election demo (3 nodes)
var nodes = [{ id: 1, term: 1 }, { id: 2, term: 1 }, { id: 3, term: 2 }];
var votes = {};
nodes.forEach(function(n) { votes[n.id] = 0; });
nodes.forEach(function(voter) {
  var cand = nodes.reduce(function(a, b) { return (b.term > a.term || (b.term === a.term && b.id > a.id)) ? b : a; });
  votes[cand.id]++;
});
var leader = Object.keys(votes).reduce(function(a, b) { return votes[a] >= votes[b] ? a : b; });
console.log("Algorithm: SigRaft | Tolerates: f crash (2f+1)");
console.log("Votes: " + JSON.stringify(votes));
console.log("Leader elected: node " + leader + " with " + votes[leader] + "/3 votes -> QUORUM PASS");

